const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let idx = 0;

function nextInt() {
    while (idx < data.length && data.charCodeAt(idx) <= 32) idx++;
    let num = 0;
    while (idx < data.length) {
        const c = data.charCodeAt(idx);
        if (c <= 32) break;
        num = num * 10 + (c - 48);
        idx++;
    }
    return num;
}

function main() {
    const N = nextInt();
    const M = nextInt();

    const adj = Array.from({ length: N + 1 }, () => []);

    for (let i = 0; i < M; i++) {
        const x = nextInt();
        const y = nextInt();
        adj[x].push(y);
        adj[y].push(x);
    }

    const visited = new Uint8Array(N + 1);

    for (let start = 1; start <= N; start++) {
        if (visited[start]) continue;

        const cur = [];
        const stack = [start];
        visited[start] = 1;

        while (stack.length > 0) {
            const v = stack.pop();
            cur.push(v);

            const neigh = adj[v];
            for (let j = 0; j < neigh.length; j++) {
                const u = neigh[j];
                if (!visited[u]) {
                    visited[u] = 1;
                    stack.push(u);
                }
            }
        }

        const size = cur.length;
        let v = -1;

        for (let j = 0; j < size; j++) {
            const x = cur[j];
            if (adj[x].length < size - 1) {
                v = x;
                break;
            }
        }

        if (v !== -1) {
            const neighbors = new Set(adj[v]);

            for (let j = 0; j < size; j++) {
                const u = cur[j];
                if (u !== v && !neighbors.has(u)) {
                    console.log(v + ' ' + u);
                    return;
                }
            }
        }
    }

    console.log('-1');
}

main();
